/**
 * @event
 * @name scwin.grd_clmSchdlNoti_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_clmSchdlNoti_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_clmSchdlNoti');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_clmSchdlNoti'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (columnId === "__rowAct") { if (r["listProcsStatCd"] === '33'|| r["listProcsStatCd"] === '36') { if (typeof scwin.openAdjReqPop === 'function') { scwin.openAdjReqPop(r["bzProcsNo"], "110"); } else { console.error('[sdd] 행 동작 미정의: scwin.openAdjReqPop (열 수정요청)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.openAdjReqPop'); } return; } if (r["listProcsStatCd"] === '30' || r["listProcsStatCd"] === '35' || r["listProcsStatCd"] === '37') { if (typeof scwin.editClmSchdlNoti === 'function') { await scwin.editClmSchdlNoti(r["bzProcsNo"], "32", r["assgnYn"]); } else { console.error('[sdd] 행 동작 미정의: scwin.editClmSchdlNoti (열 제출)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.editClmSchdlNoti'); } return; } return; } if (r["listProcsStatCd"] !== '30' && r["listProcsStatCd"] !== '37' && r["listProcsStatCd"] !== '35') { if (typeof scwin.viewDetail === 'function') { await scwin.viewDetail(r["bzProcsNo"]); } else { console.error('[sdd] 행 동작 미정의: scwin.viewDetail (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.viewDetail'); } return; }
        if (r["listProcsStatCd"] === '30') { if (typeof scwin.viewDetail === 'function') { await scwin.viewDetail(r["bzProcsNo"]); } else { console.error('[sdd] 행 동작 미정의: scwin.viewDetail (열 작성중)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.viewDetail'); } return; }
        if (r["listProcsStatCd"] === '35') { if (typeof scwin.viewDetail === 'function') { await scwin.viewDetail(r["bzProcsNo"]); } else { console.error('[sdd] 행 동작 미정의: scwin.viewDetail (열 수정가능)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.viewDetail'); } return; }
        if (r["listProcsStatCd"] === '37') { if (typeof scwin.viewDetail === 'function') { await scwin.viewDetail(r["bzProcsNo"]); } else { console.error('[sdd] 행 동작 미정의: scwin.viewDetail (열 재작성)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.viewDetail'); } return; }
        if (typeof scwin.viewDetail === 'function') { await scwin.viewDetail(r["bzProcsNo"]); } else { console.error('[sdd] 행 동작 미정의: scwin.viewDetail (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.viewDetail'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_clmSchdlNoti.oncellclick' });
    }
};

